class VisibilityDemo {
    public String publicField = "PUBLIC: Everywhere";
    protected String protectedField = "PROTECTED: Package + Subclass";
    String defaultField = "PACKAGE-PRIVATE: Same package only";
    private String privateField = "PRIVATE: Same class only";

    public void showInsideClass() {
        System.out.println(publicField);
        System.out.println(protectedField);
        System.out.println(defaultField);
        System.out.println(privateField);
    }
}

public class AccessControlDemo {
    public static void main(String[] args) {
        VisibilityDemo demo = new VisibilityDemo();
        System.out.println("--- Accessing from same package ---");
        System.out.println(demo.publicField);
        System.out.println(demo.protectedField);
        System.out.println(demo.defaultField);
        // demo.privateField would cause a compilation error here!
        System.out.println("Private field is inaccessible directly.");
    }
}

