public class AccessMatrixEngine {
    public static boolean canAccess(String modifier, String context) {
        if ("public".equalsIgnoreCase(modifier)) return true;
        if ("SAME_CLASS".equalsIgnoreCase(context)) return true;
        if ("private".equalsIgnoreCase(modifier)) return false;
        if ("SAME_PACKAGE".equalsIgnoreCase(context)) return true;
        if ("DIFF_PACKAGE_SUBCLASS".equalsIgnoreCase(context)) {
            return "protected".equalsIgnoreCase(modifier);
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println("protected in diff pkg subclass: " + canAccess("protected", "DIFF_PACKAGE_SUBCLASS"));
        System.out.println("default in diff pkg subclass: " + canAccess("default", "DIFF_PACKAGE_SUBCLASS"));
        System.out.println("private in same package: " + canAccess("private", "SAME_PACKAGE"));
    }
}

