public class TopLevelValidator {
    public static boolean isValidTopLevelClassModifier(String modifier) {
        if (modifier == null) return false;
        String m = modifier.trim().toLowerCase();
        return m.equals("public") || m.equals("default") || m.equals("") || m.equals("package-private");
    }

    public static void main(String[] args) {
        System.out.println("public: " + isValidTopLevelClassModifier("public"));
        System.out.println("private: " + isValidTopLevelClassModifier("private"));
        System.out.println("package-private: " + isValidTopLevelClassModifier("default"));
    }
}

