public class EncapsulationShieldDemo {
    static class SecureToken {
        private final String token;
        public SecureToken(String token) {
            this.token = token;
        }
        boolean isValid() {
            return token != null && token.length() == 16;
        }
    }

    public static void main(String[] args) {
        SecureToken t1 = new SecureToken("1234567890abcdef");
        SecureToken t2 = new SecureToken("short");
        System.out.println("T1 valid: " + t1.isValid());
        System.out.println("T2 valid: " + t2.isValid());
    }
}

