}

practiceProblems.solution:
public class StrictnessRanker {
    private static int rank(String mod) {
        switch (mod.toLowerCase()) {
            case "private": return 1;
            case "default":
            case "package-private": return 2;
            case "protected": return 3;
            case "public": return 4;
            default: return 0;
        }
    }

    public static int compareStrictness(String mod1, String mod2) {
        return Integer.compare(rank(mod1), rank(mod2));
    }

    public static void main(String[] args) {
        System.out.println(compareStrictness("private", "public") < 0);
        System.out.println(compareStrictness("protected", "default") > 0);
    }
}

