practiceProblems.solution:
public class OverrideVisibilityValidator {
    private static int rank(String mod) {
        switch (mod.toLowerCase()) {
            case "private": return 1;
            case "default": return 2;
            case "protected": return 3;
            case "public": return 4;
            default: return 0;
        }
    }

    public static boolean isLegalOverrideAccess(String superMod, String subMod) {
        return rank(subMod) >= rank(superMod);
    }

    public static void main(String[] args) {
        System.out.println("public -> protected: " + isLegalOverrideAccess("public", "protected"));
        System.out.println("protected -> public: " + isLegalOverrideAccess("protected", "public"));
        System.out.println("default -> default: " + isLegalOverrideAccess("default", "default"));
    }
}

